from abc import ABCMeta, abstractmethod
import logging
import six
import socket
from taf.transport.ssh.exceptions import CommandOutputTimeoutError
from taf.internal.execution.base import Process, InputStream, OutputStream, TimeoutError
from select import select

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SshProcess(Process):
    """
    Running process with input and output streams.
    """

    def __init__(self, ssh_process, **kwargs):
        super(SshProcess, self).__init__(**kwargs)
        self._ssh_process = ssh_process

    def wait(self, timeout=None):
        """
        Wait until the process finishes execution.

        :param float timeout:
            wait timeout seconds for the process to finish
            (forever, if timeout is None)
        :raises: TimeoutError, if process did not finish after timeout seconds
        """
        try:
            self._ssh_process.join(timeout=timeout)
        except CommandOutputTimeoutError:
            raise TimeoutError(self._command, timeout)

    def _get_is_running(self):
        """
        Return True, if the process is still running.

        :return:
        """
        return self._ssh_process.is_alive()

    def _get_exit_status(self):
        """
        Return the exit status of a terminated process.

        :return: exit status
        :rtpye: int
        """
        return self._ssh_process.get_exit_code()

    def _read_output(self):  # noqa: C901
        """
        Read stdout and stderr from the SSH channel without logging.

        Uses select() on the SSH channel to avoid blocking.
        Uses channel.closed instead of exit_status_ready() to determine when
        all data has been received, as exit_status_ready() can return True
        before all data has been buffered locally (race condition).

        :return: stdout data, stderr data
        :rtype: bytes, bytes
        """
        channel = self.stdout._buffered_file.channel
        stdout_data = bytearray()
        stderr_data = bytearray()

        while not channel.closed or channel.recv_ready() or channel.recv_stderr_ready():
            rlist, _, _ = select([channel], [], [], None)
            if channel in rlist:
                if channel.recv_ready():
                    data = channel.recv(4096)
                    stdout_data.extend(data)

                if channel.recv_stderr_ready():
                    data = channel.recv_stderr(4096)
                    stderr_data.extend(data)

        return bytes(stdout_data), bytes(stderr_data)


class SshStream(object):
    """
    Base class for streams of SSH executor.
    """

    def __init__(self, buffered_file, **kwargs):
        """
        Create an SshStream.

        :param BufferedFile buffered_file: BufferedFile subclass instance (paramiko)
        """

        super(SshStream, self).__init__(**kwargs)
        self._buffered_file = buffered_file


class SshInputStream(InputStream, SshStream):
    """
    Input stream of a process (stdin), where input data can be written to.
    """

    def __init__(self, use_tty, **kwargs):
        super(SshInputStream, self).__init__(**kwargs)
        self._use_tty = use_tty

    def write(self, data):
        """
        Write data to stream.

        :param bytes data: data to be written into the input stream
        """
        logger.debug("writing {data!r} to input stream".format(data=data))
        self._buffered_file.write(data=data)

    def close(self):
        """
        Close the input stream.
        """
        logger.debug("closing")
        if self._use_tty:
            self._buffered_file.channel.send(b"\x04")
        else:
            self._buffered_file.channel.shutdown_write()


@six.add_metaclass(ABCMeta)
class SshBaseOutputStream(OutputStream, SshStream):
    """
    Base class for output streams of SSH executor.
    """

    def _read(self, size=None, timeout=None):
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)
        :param float timeout: timeout in seconds to wait for the next character

        :return: read data
        :rtype: bytes
        """
        old_timeout = self._buffered_file.channel.gettimeout()
        self._buffered_file.channel.settimeout(timeout)
        try:
            data = self._do_read(size)
        except socket.timeout:
            raise TimeoutError()
        finally:
            self._buffered_file.channel.settimeout(old_timeout)
        return data

    @abstractmethod
    def _do_read(self, size):
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)

        :return: read data
        :rtype: bytes
        """


class SshOutputStream(SshBaseOutputStream):
    """
    Stdout stream of SSH executor.
    """

    _stream_name = "stdout"

    def _do_read(self, size):
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)

        :return: read data
        :rtype: bytes
        """
        if size is None:
            data = b""
            while True:
                new_data = self._buffered_file.channel.recv(4096)
                if not new_data:
                    return data
                data += new_data
        else:
            return self._buffered_file.channel.recv(size)


class SshErrorStream(SshBaseOutputStream):
    """
    Stderr stream of SSH executor.
    """

    _stream_name = "stderr"

    def _do_read(self, size):
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)

        :return: read data
        :rtype: bytes
        """
        if size is None:
            data = b""
            while True:
                new_data = self._buffered_file.channel.recv_stderr(4096)
                if not new_data:
                    return data
                data += new_data
        else:
            return self._buffered_file.channel.recv_stderr(size)
